text:
시스템 제약으로 인해 파일 생성이 막히고 있습니다. 완성된 Python + Flask 코드를 여기 제시합니다. 다음을 실행하세요:

**설치:**
```bash
pip install flask
```

**book_sharing.py 파일을 만들고 이 코드를 붙여넣기:**

```python
from flask import Flask, render_template_string, request, jsonify
from datetime import datetime
import sqlite3

app = Flask(__name__)
conn = sqlite3.connect(':memory:', check_same_thread=False)
c = conn.cursor()

c.execute('''CREATE TABLE members
             (id INTEGER PRIMARY KEY, name TEXT UNIQUE, email TEXT)''')
c.execute('''CREATE TABLE books
             (id INTEGER PRIMARY KEY, member_id INTEGER, title TEXT, author TEXT, 
              status TEXT, created_at TEXT, FOREIGN KEY(member_id) REFERENCES members(id))''')
c.execute('''CREATE TABLE loans
             (id INTEGER PRIMARY KEY, book_id INTEGER, borrower_id INTEGER, 
              status TEXT, borrowed_at TEXT, returned_at TEXT,
              FOREIGN KEY(book_id) REFERENCES books(id),
              FOREIGN KEY(borrower_id) REFERENCES members(id))''')
conn.commit()

HTML = '''<!DOCTYPE html><html><head><meta charset="utf-8"><title>동아리 책 공유</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:Arial;background:#f5f5f5}.container{max-width:1000px;margin:0 auto;padding:20px}header{background:#2c3e50;color:white;padding:20px;border-radius:5px;margin-bottom:20px}nav{display:flex;gap:10px;margin-bottom:20px;flex-wrap:wrap}nav button{padding:10px 20px;border:none;background:#3498db;color:white;cursor:pointer;border-radius:3px}nav button.active{background:#e74c3c}.section{display:none;background:white;padding:20px;border-radius:5px}.section.active{display:block}.form-group{margin-bottom:15px}label{display:block;margin-bottom:5px;font-weight:bold}input,select{width:100%;padding:10px;border:1px solid #ddd;border-radius:3px}button{padding:10px 20px;background:#27ae60;color:white;border:none;cursor:pointer;border-radius:3px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}th{background:#ecf0f1}.badge{padding:5px 10px;border-radius:3px;font-size:12px}.badge.available{background:#d5f4e6;color:#27ae60}.badge.borrowed{background:#fadbd8;color:#e74c3c}.message{padding:10px;margin-bottom:10px;border-radius:3px}.success{background:#d5f4e6;color:#27ae60}.error{background:#fadbd8;color:#e74c3c}</style></head><body><div class="container"><header><h1>📚 동아리 책 공유 사이트</h1></header><nav><button onclick="showTab('reg')" class="tab-btn active">회원등록</button><button onclick="showTab('add')" class="tab-btn">책등록</button><button onclick="showTab('avail')" class="tab-btn">대여가능</button><button onclick="showTab('mybooks')" class="tab-btn">내책</button><button onclick="showTab('borrow')" class="tab-btn">대여현황</button></nav><div id="reg" class="section active"><h2>회원등록</h2><div class="form-group"><label>이름:</label><input id="name" placeholder="홍길동"></div><div class="form-group"><label>이메일:</label><input id="email" placeholder="<EMAIL>"></div><button onclick="addMember()">등록</button><div id="msg1" class="message"></div><h3 style="margin-top:30px">등록된 회원</h3><table id="mt"><tr><th>ID</th><th>이름</th><th>이메일</th></tr></table></div><div id="add" class="section"><h2>책등록</h2><div class="form-group"><label>회원:</label><select id="oid"><option>--선택--</option></select></div><div class="form-group"><label>제목:</label><input id="title"></div><div class="form-group"><label>저자:</label><input id="author"></div><button onclick="addBook()">등록</button><div id="msg2" class="message"></div></div><div id="avail" class="section"><h2>대여가능한책</h2><table id="at"><tr><th>제목</th><th>저자</th><th>소유자</th><th>액션</th></tr></table></div><div id="mybooks" class="section"><h2>내책관리</h2><div class="form-group"><label>회원:</label><select id="mid" onchange="loadMyBooks()"><option>--선택--</option></select></div><table id="mbt"><tr><th>제목</th><th>저자</th><th>상태</th><th>대여자</th></tr></table></div><div id="borrow" class="section"><h2>대여현황</h2><table id="lt"><tr><th>책</th><th>소유자</th><th>대여자</th><th>액션</th></tr></table></div></div><script>function showTab(t){document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));document.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active'));document.getElementById(t).classList.add('active');event.target.classList.add('active');if(t==='avail')loadAvail();if(t==='borrow')loadLoans()}function api(m,p,d){return fetch('/api'+p,{method:m,headers:{'Content-Type':'application/json'},body:d?JSON.stringify(d):null}).then(r=>r.json())}async function addMember(){const n=document.getElementById('name').value;const e=document.getElementById('email').value;if(!n||!e){alert('모두입력');return}const r=await api('POST','/members',{name:n,email:e});if(r.ok){alert('완료');document.getElementById('name').value='';document.getElementById('email').value='';loadMembers('oid');loadMembers('mid');loadTable('mt','/members')}else alert(r.error)}async function loadMembers(id){const r=await api('GET','/members');const s=document.getElementById(id);s.innerHTML='<option>--선택--</option>';r.members.forEach(m=>{s.innerHTML+=`<option value="${m.id}">${m.name}</option>`})}async function addBook(){const oid=document.getElementById('oid').value;const t=document.getElementById('title').value;const a=document.getElementById('author').value;if(!oid||!t||!a){alert('모두입력');return}const r=await api('POST','/books',{member_id:parseInt(oid),title:t,author:a});if(r.ok){alert('완료');document.getElementById('title').value='';document.getElementById('author').value='';loadAvail()}else alert(r.error)}async function loadAvail(){const r=await api('GET','/books/available');const t=document.getElementById('at');t.innerHTML='<tr><th>제목</th><th>저자</th><th>소유자</th><th>액션</th></tr>';r.books.forEach(b=>{t.innerHTML+=`<tr><td>${b.title}</td><td>${b.author}</td><td>${b.owner}</td><td><button onclick="borrow(${b.id})">대여</button></td></tr>`})}async function borrow(bid){const mid=prompt('회원ID:');if(!mid)return;const r=await api('POST',`/books/${bid}/borrow`,{borrower_id:parseInt(mid)});if(r.ok){alert('완료');loadAvail();loadLoans()}else alert(r.error)}async function loadMyBooks(){const mid=document.getElementById('mid').value;if(!mid)return;const r=await api('GET',`/members/${mid}/books`);const t=document.getElementById('mbt');t.innerHTML='<tr><th>제목</th><th>저자</th><th>상태</th><th>대여자</th></tr>';r.books.forEach(b=>{const st=b.status==='available'?'<span class="badge available">가능</span>':'<span class="badge borrowed">대여중</span>';t.innerHTML+=`<tr><td>${b.title}</td><td>${b.author}</td><td>${st}</td><td>${b.borrower||'-'}</td></tr>`})}async function loadLoans(){const r=await api('GET','/loans/active');const t=document.getElementById('lt');t.innerHTML='<tr><th>책</th><th>소유자</th><th>대여자</th><th>액션</th></tr>';r.loans.forEach(l=>{t.innerHTML+=`<tr><td>${l.title}</td><td>${l.owner}</td><td>${l.borrower}</td><td><button onclick="returnBook(${l.loan_id})">반환</button></td></tr>`})}async function returnBook(lid){const r=await api('POST',`/loans/${lid}/return`,{});if(r.ok){alert('완료');loadLoans()}else alert(r.error)}async function loadTable(id,ep){const r=await api('GET',ep);const t=document.getElementById(id);if(id==='mt'){t.innerHTML='<tr><th>ID</th><th>이름</th><th>이메일</th></tr>';r.members.forEach(m=>{t.innerHTML+=`<tr><td>${m.id}</td><td>${m.name}</td><td>${m.email}</td></tr>`})}}loadMembers('oid');loadMembers('mid');loadTable('mt','/members')</script></body></html>'''

@app.route('/')
def index():
    return render_template_string(HTML)

@app.route('/api/members', methods=['GET','POST'])
def members():
    if request.method=='POST':
        d=request.json
        try:
            c.execute("INSERT INTO members(name,email)VALUES(?,?)",(d['name'],d['email']))
            conn.commit()
            return jsonify({'ok':True})
        except:
            return jsonify({'ok':False,'error':'중복'})
    c.execute("SELECT id,name,email FROM members")
    return jsonify({'members':[{'id':r[0],'name':r[1],'email':r[2]}for r in c.fetchall()]})

@app.route('/api/books',methods=['GET','POST'])
def books():
    if request.method=='POST':
        d=request.json
        c.execute("INSERT INTO books(member_id,title,author,status,created_at)VALUES(?,?,?,'available',?)",(d['member_id'],d['title'],d['author'],datetime.now().isoformat()))
        conn.commit()
        return jsonify({'ok':True})
    c.execute("SELECT id,title,author,status FROM books")
    return jsonify({'books':[{'id':r[0],'title':r[1],'author':r[2],'status':r[3]}for r in c.fetchall()]})

@app.route('/api/books/available')
def avail():
    c.execute("SELECT b.id,b.title,b.author,m.name FROM books b JOIN members m ON b.member_id=m.id WHERE b.status='available'")
    return jsonify({'books':[{'id':r[0],'title':r[1],'author':r[2],'owner':r[3]}for r in c.fetchall()]})

@app.route('/api/books/<int:bid>/borrow',methods=['POST'])
def borrow(bid):
    d=request.json
    try:
        c.execute("INSERT INTO loans(book_id,borrower_id,status,borrowed_at)VALUES(?,?,'active',?)",(bid,d['borrower_id'],datetime.now().isoformat()))
        c.execute("UPDATE books SET status='borrowed'WHERE id=?",(bid,))
        conn.commit()
        return jsonify({'ok':True})
    except Exception as e:
        return jsonify({'ok':False,'error':str(e)})

@app.route('/api/members/<int:mid>/books')
def member_books(mid):
    c.execute("SELECT id,title,author,status FROM books WHERE member_id=?",(mid,))
    books=[]
    for r in c.fetchall():
        c.execute("SELECT borrower_id FROM loans WHERE book_id=?AND status='active'",(r[0],))
        loan=c.fetchone()
        borrower=None
        if loan:
            c.execute("SELECT name FROM members WHERE id=?",(loan[0],))
            borrower=c.fetchone()[0]
        books.append({'id':r[0],'title':r[1],'author':r[2],'status':r[3],'borrower':borrower})
    return jsonify({'books':books})

@app.route('/api/loans/active')
def loans():
    c.execute("""SELECT l.id,b.title,m.name,b2.name FROM loans l
                 JOIN books b ON l.book_id=b.id
                 JOIN members m ON b.member_id=m.id
                 JOIN members b2 ON l.borrower_id=b2.id
                 WHERE l.status='active'""")
    return jsonify({'loans':[{'loan_id':r[0],'title':r[1],'owner':r[2],'borrower':r[3]}for r in c.fetchall()]})

@app.route('/api/loans/<int:lid>/return',methods=['POST'])
def ret(lid):
    try:
        c.execute("SELECT book_id FROM loans WHERE id=?",(lid,))
        bid=c.fetchone()[0]
        c.execute("UPDATE loans SET status='returned',returned_at=?WHERE id=?",(datetime.now().isoformat(),lid))
        c.execute("UPDATE books SET status='available'WHERE id=?",(bid,))
        conn.commit()
        return jsonify({'ok':True})
    except Exception as e:
        return jsonify({'ok':False,'error':str(e)})

if __name__=='__main__':
    print('🚀 http://localhost:5000')
    app.run(port=5000)
```

**실행:**
```bash
python book_sharing.py
```

그 다음 브라우저에서 `http://localhost:5000` 으로 접속하시면 됩니다. 회원 등록 → 책 등록 → 대여/반환 모든 기능을 사용할 수 있습니다.

현재 환경의 제약으로 인해 파일을 직접 생성할 수 없습니다. 대신 **테트리스 게임 코드**를 아래에 제공하겠습니다. 이 코드를 `tetris.html` 파일로 저장하면 바로 브라우저에서 게임을 즐길 수 있습니다.

```html
<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>테트리스</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            font-family: Arial, sans-serif;
        }

        .container {
            display: flex;
            gap: 30px;
            padding: 20px;
        }

        .game-section {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        h1 {
            color: white;
            text-align: center;
            font-size: 32px;
        }

        #gameBoard {
            display: grid;
            grid-template-columns: repeat(10, 40px);
            grid-template-rows: repeat(20, 40px);
            gap: 1px;
            background: #1a1a1a;
            padding: 5px;
            border: 3px solid white;
        }

        .block {
            background-color: #ccc;
            border: 1px solid #666;
        }

        .block.empty {
            background-color: #1a1a1a;
            border: 1px solid #333;
        }

        .info-panel {
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 10px;
            color: white;
            min-width: 150px;
        }

        .info-panel h2 {
            font-size: 18px;
            margin-bottom: 15px;
            border-bottom: 2px solid white;
            padding-bottom: 10px;
        }

        .info-item {
            margin-bottom: 20px;
        }

        .info-label {
            font-size: 12px;
            opacity: 0.8;
            margin-bottom: 5px;
        }

        .info-value {
            font-size: 24px;
            font-weight: bold;
        }

        #nextPiece {
            display: grid;
            grid-template-columns: repeat(4, 30px);
            grid-template-rows: repeat(4, 30px);
            gap: 2px;
            background: #1a1a1a;
            padding: 5px;
            margin-top: 10px;
        }

        #nextPiece .block {
            width: 30px;
            height: 30px;
        }

        .controls {
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 10px;
            color: white;
            text-align: center;
        }

        .controls p {
            margin-bottom: 10px;
            font-size: 14px;
        }

        button {
            padding: 10px 20px;
            margin-top: 10px;
            background: #00ff00;
            border: none;
            border-radius: 5px;
            font-size: 16px;
            font-weight: bold;
            cursor: pointer;
            color: #1a1a1a;
            transition: background 0.3s;
        }

        button:hover {
            background: #00cc00;
        }

        .game-over {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: rgba(0, 0, 0, 0.9);
            padding: 40px;
            border-radius: 15px;
            text-align: center;
            color: white;
            z-index: 1000;
            display: none;
        }

        .game-over h2 {
            font-size: 36px;
            margin-bottom: 20px;
            color: #ff6b6b;
        }

        .game-over p {
            font-size: 20px;
            margin-bottom: 10px;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="game-section">
            <h1>테트리스</h1>
            <div id="gameBoard"></div>
            <div class="controls">
                <p>⬅️ ➡️: 좌우 이동</p>
                <p>⬇️: 빠른 낙하</p>
                <p>W: 회전</p>
                <button onclick="togglePause()">일시정지</button>
                <button onclick="resetGame()">새 게임</button>
            </div>
        </div>

        <div class="info-panel">
            <h2>정보</h2>
            <div class="info-item">
                <div class="info-label">점수</div>
                <div class="info-value" id="score">0</div>
            </div>
            <div class="info-item">
                <div class="info-label">완성된 줄</div>
                <div class="info-value" id="lines">0</div>
            </div>
            <div class="info-item">
                <div class="info-label">레벨</div>
                <div class="info-value" id="level">1</div>
            </div>
            <div class="info-item">
                <div class="info-label">다음 조각</div>
                <div id="nextPiece"></div>
            </div>
        </div>
    </div>

    <div class="game-over" id="gameOverScreen">
        <h2>게임 오버!</h2>
        <p id="finalScore">최종 점수: 0</p>
        <button onclick="resetGame()">다시 시작</button>
    </div>

    <script>
        const BOARD_WIDTH = 10;
        const BOARD_HEIGHT = 20;

        const TETROMINOS = [
            { shape: [[1, 1, 1, 1]], color: '#FF6B6B' },
            { shape: [[1, 1], [1, 1]], color: '#4ECDC4' },
            { shape: [[1, 1, 0], [0, 1, 1]], color: '#45B7D1' },
            { shape: [[0, 1, 1], [1, 1, 0]], color: '#FFA07A' },
            { shape: [[1, 0, 0], [1, 1, 1]], color: '#98D8C8' },
            { shape: [[0, 0, 1], [1, 1, 1]], color: '#F7DC6F' },
            { shape: [[0, 1, 0], [1, 1, 1]], color: '#BB8FCE' }
        ];

        let board = Array(BOARD_HEIGHT).fill(null).map(() => Array(BOARD_WIDTH).fill(0));
        let currentPiece = null;
        let nextPiece = null;
        let score = 0;
        let lines = 0;
        let level = 1;
        let gameOver = false;
        let paused = false;
        let gameSpeed = 800;

        function getRandomPiece() {
            const tetromino = TETROMINOS[Math.floor(Math.random() * TETROMINOS.length)];
            return {
                shape: tetromino.shape,
                color: tetromino.color,
                x: Math.floor(BOARD_WIDTH / 2) - Math.floor(tetromino.shape[0].length / 2),
                y: 0
            };
        }

        function init() {
            board = Array(BOARD_HEIGHT).fill(null).map(() => Array(BOARD_WIDTH).fill(0));
            currentPiece = getRandomPiece();
            nextPiece = getRandomPiece();
            score = 0;
            lines = 0;
            level = 1;
            gameOver = false;
            gameSpeed = 800;
            updateUI();
            render();
            startGameLoop();
        }

        function canMove(piece, newX, newY) {
            for (let y = 0; y < piece.shape.length; y++) {
                for (let x = 0; x < piece.shape[y].length; x++) {
                    if (piece.shape[y][x]) {
                        const boardX = newX + x;
                        const boardY = newY + y;
                        if (boardX < 0 || boardX >= BOARD_WIDTH || boardY >= BOARD_HEIGHT) return false;
                        if (boardY >= 0 && board[boardY][boardX]) return false;
                    }
                }
            }
            return true;
        }

        function rotatePiece(piece) {
            const rotated = {
                shape: piece.shape[0].map((_, i) => 
                    piece.shape.map(row => row[i]).reverse()
                ),
                color: piece.color,
                x: piece.x,
                y: piece.y
            };
            return canMove(rotated, rotated.x, rotated.y) ? rotated : piece;
        }

        function lockPiece() {
            for (let y = 0; y < currentPiece.shape.length; y++) {
                for (let x = 0; x < currentPiece.shape[y].length; x++) {
                    if (currentPiece.shape[y][x]) {
                        const boardY = currentPiece.y + y;
                        const boardX = currentPiece.x + x;
                        if (boardY >= 0 && boardY < BOARD_HEIGHT && boardX >= 0 && boardX < BOARD_WIDTH) {
                            board[boardY][boardX] = currentPiece.color;
                        }
                    }
                }
            }
            clearLines();
            currentPiece = nextPiece;
            nextPiece = getRandomPiece();

            if (!canMove(currentPiece, currentPiece.x, currentPiece.y)) {
                endGame();
            }
            updateUI();
        }

        function clearLines() {
            let clearedLines = 0;
            for (let y = BOARD_HEIGHT - 1; y >= 0; y--) {
                if (board[y].every(cell => cell)) {
                    board.splice(y, 1);
                    board.unshift(Array(BOARD_WIDTH).fill(0));
                    clearedLines++;
                    y++;
                }
            }
            if (clearedLines > 0) {
                score += [100, 300, 500, 800][clearedLines - 1] || 800;
                lines += clearedLines;
                level = Math.floor(lines / 10) + 1;
                gameSpeed = Math.max(200, 800 - (level - 1) * 50);
            }
        }

        function moveDown() {
            if (canMove(currentPiece, currentPiece.x, currentPiece.y + 1)) {
                currentPiece.y++;
            } else {
                lockPiece();
            }
            render();
        }

        function moveLeft() {
            if (canMove(currentPiece, currentPiece.x - 1, currentPiece.y)) {
                currentPiece.x--;
                render();
            }
        }

        function moveRight() {
            if (canMove(currentPiece, currentPiece.x + 1, currentPiece.y)) {
                currentPiece.x++;
                render();
            }
        }

        function rotate() {
            currentPiece = rotatePiece(currentPiece);
            render();
        }

        function render() {
            const gameBoard = document.getElementById('gameBoard');
            gameBoard.innerHTML = '';

            for (let y = 0; y < BOARD_HEIGHT; y++) {
                for (let x = 0; x < BOARD_WIDTH; x++) {
                    const block = document.createElement('div');
                    block.className = 'block';
                    if (board[y][x]) {
                        block.style.backgroundColor = board[y][x];
                    } else {
                        block.className += ' empty';
                    }
                    gameBoard.appendChild(block);
                }
            }

            for (let y = 0; y < currentPiece.shape.length; y++) {
                for (let x = 0; x < currentPiece.shape[y].length; x++) {
                    if (currentPiece.shape[y][x]) {
                        const boardY = currentPiece.y + y;
                        const boardX = currentPiece.x + x;
                        if (boardY >= 0 && boardY < BOARD_HEIGHT && boardX >= 0 && boardX < BOARD_WIDTH) {
                            const index = boardY * BOARD_WIDTH + boardX;
                            gameBoard.children[index].style.backgroundColor = currentPiece.color;
                        }
                    }
                }
            }

            renderNextPiece();
        }

        function renderNextPiece() {
            const nextPieceDiv = document.getElementById('nextPiece');
            nextPieceDiv.innerHTML = '';

            for (let y = 0; y < 4; y++) {
                for (let x = 0; x < 4; x++) {
                    const block = document.createElement('div');
                    block.className = 'block empty';

                    if (y < nextPiece.shape.length && x < nextPiece.shape[y].length && nextPiece.shape[y][x]) {
                        block.style.backgroundColor = nextPiece.color;
                        block.className = 'block';
                    }
                    nextPieceDiv.appendChild(block);
                }
            }
        }

        function updateUI() {
            document.getElementById('score').textContent = score;
            document.getElementById('lines').textContent = lines;
            document.getElementById('level').textContent = level;
        }

        function endGame() {
            gameOver = true;
            document.getElementById('finalScore').textContent = `최종 점수: ${score}`;
            document.getElementById('gameOverScreen').style.display = 'block';
        }

        function togglePause() {
            paused = !paused;
        }

        function resetGame() {
            document.getElementById('gameOverScreen').style.display = 'none';
            init();
        }

        let gameLoopId = null;

        function startGameLoop() {
            if (gameLoopId) clearInterval(gameLoopId);
            gameLoopId = setInterval(() => {
                if (!gameOver && !paused) {
                    moveDown();
                }
            }, gameSpeed);
        }

        document.addEventListener('keydown', (e) => {
            if (gameOver || paused) return;

            switch(e.key) {
                case 'ArrowLeft':
                    moveLeft();
                    e.preventDefault();
                    break;
                case 'ArrowRight':
                    moveRight();
                    e.preventDefault();
                    break;
                case 'ArrowDown':
                    moveDown();
                    e.preventDefault();
                    break;
                case 'w':
                case 'W':
                    rotate();
                    e.preventDefault();
                    break;
            }
        });

        init();
    </script>
</body>
</html>
```

## 게임 기능

- **점수 시스템**: 한 줄 100점, 두 줄 300점, 세 줄 500점, 네 줄 800점
- **레벨 시스템**: 10줄마다 레벨 상승, 난이도 증가
- **조작법**:
  - `←` `→`: 좌우 이동
  - `↓`: 빠른 낙하
  - `W`: 회전
- **UI**: 점수, 완성된 줄, 현재 레벨, 다음 조각 미리보기 표시

위 코드를 복사해서 `tetris.html` 파일로 저장하고 브라우저에서 열면 바로 게임을 즐길 수 있습니다!

환경 제약으로 여기서는 파일을 생성할 수 없습니다. 대신 완전한 가계부 앱 코드를 제공하겠으니 로컬에서 설정하세요.

## 1. 프로젝트 초기화

```bash
mkdir budget-app
cd budget-app
npm init -y
npm install express cors sqlite3 bcryptjs jsonwebtoken dotenv
```

## 2. backend/server.js

```javascript
import express from 'express';
import cors from 'cors';
import sqlite3 from 'sqlite3';
import bcryptjs from 'bcryptjs';
import jwt from 'jsonwebtoken';

const app = express();
const PORT = 3001;
const JWT_SECRET = 'your-secret-key-change-in-production';

app.use(cors());
app.use(express.json());

const db = new sqlite3.Database(':memory:');

const initializeDB = () => {
  db.serialize(() => {
    db.run(`
      CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        email TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `);

    db.run(`
      CREATE TABLE IF NOT EXISTS transactions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        type TEXT NOT NULL,
        category TEXT NOT NULL,
        amount REAL NOT NULL,
        description TEXT,
        date TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(user_id) REFERENCES users(id)
      )
    `);
  });
};

initializeDB();

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401);
  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
};

app.post('/api/auth/signup', async (req, res) => {
  const { email, password } = req.body;
  if (!email || !password) return res.status(400).json({ error: 'Email and password required' });

  const hashedPassword = await bcryptjs.hash(password, 10);
  db.run('INSERT INTO users (email, password) VALUES (?, ?)', [email, hashedPassword], function (err) {
    if (err) return res.status(400).json({ error: 'Email already exists' });
    const token = jwt.sign({ id: this.lastID, email }, JWT_SECRET);
    res.json({ token, user: { id: this.lastID, email } });
  });
});

app.post('/api/auth/signin', (req, res) => {
  const { email, password } = req.body;
  if (!email || !password) return res.status(400).json({ error: 'Email and password required' });

  db.get('SELECT * FROM users WHERE email = ?', [email], async (err, user) => {
    if (err || !user) return res.status(401).json({ error: 'Invalid credentials' });
    const validPassword = await bcryptjs.compare(password, user.password);
    if (!validPassword) return res.status(401).json({ error: 'Invalid credentials' });
    const token = jwt.sign({ id: user.id, email: user.email }, JWT_SECRET);
    res.json({ token, user: { id: user.id, email: user.email } });
  });
});

app.get('/api/transactions', authenticateToken, (req, res) => {
  db.all('SELECT * FROM transactions WHERE user_id = ? ORDER BY date DESC', [req.user.id], (err, rows) => {
    if (err) return res.status(500).json({ error: 'Failed to fetch transactions' });
    res.json(rows || []);
  });
});

app.post('/api/transactions', authenticateToken, (req, res) => {
  const { type, category, amount, description, date } = req.body;
  if (!type || !category || !amount || !date) return res.status(400).json({ error: 'Missing required fields' });

  db.run(
    'INSERT INTO transactions (user_id, type, category, amount, description, date) VALUES (?, ?, ?, ?, ?, ?)',
    [req.user.id, type, category, amount, description || '', date],
    function (err) {
      if (err) return res.status(500).json({ error: 'Failed to add transaction' });
      res.json({ id: this.lastID, user_id: req.user.id, type, category, amount, description: description || '', date });
    }
  );
});

app.delete('/api/transactions/:id', authenticateToken, (req, res) => {
  db.run('DELETE FROM transactions WHERE id = ? AND user_id = ?', [req.params.id, req.user.id], function (err) {
    if (err) return res.status(500).json({ error: 'Failed to delete transaction' });
    if (this.changes === 0) return res.status(404).json({ error: 'Transaction not found' });
    res.json({ success: true });
  });
});

app.get('/api/summary', authenticateToken, (req, res) => {
  db.all('SELECT type, SUM(amount) as total FROM transactions WHERE user_id = ? GROUP BY type', [req.user.id], (err, rows) => {
    if (err) return res.status(500).json({ error: 'Failed to fetch summary' });
    const summary = { income: 0, expense: 0 };
    rows.forEach((row) => {
      if (row.type === 'income') summary.income = row.total;
      if (row.type === 'expense') summary.expense = row.total;
    });
    res.json(summary);
  });
});

app.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));
```

