## 4. frontend/src/App.js

```javascript
import { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';

const API = axios.create({ baseURL: 'http://localhost:3001/api' });

export default function App() {
  const [user, setUser] = useState(null);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [transactions, setTransactions] = useState([]);
  const [summary, setSummary] = useState({ income: 0, expense: 0 });
  const [form, setForm] = useState({ type: 'expense', category: '식비', amount: '', description: '', date: new Date().toISOString().split('T')[0] });

  const token = localStorage.getItem('token');

  useEffect(() => {
    if (token) {
      API.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      fetchTransactions();
      fetchSummary();
    }
  }, [token]);

  const fetchTransactions = async () => {
    try {
      const res = await API.get('/transactions');
      setTransactions(res.data);
    } catch (err) {
      console.error('Failed to fetch transactions');
    }
  };

  const fetchSummary = async () => {
    try {
      const res = await API.get('/summary');
      setSummary(res.data);
    } catch (err) {
      console.error('Failed to fetch summary');
    }
  };

  const handleSignup = async () => {
    try {
      const res = await API.post('/auth/signup', { email, password });
      localStorage.setItem('token', res.data.token);
      setUser(res.data.user);
      setEmail('');
      setPassword('');
      API.defaults.headers.common['Authorization'] = `Bearer ${res.data.token}`;
      fetchTransactions();
      fetchSummary();
    } catch (err) {
      alert('회원가입 실패');
    }
  };

  const handleSignin = async () => {
    try {
      const res = await API.post('/auth/signin', { email, password });
      localStorage.setItem('token', res.data.token);
      setUser(res.data.user);
      setEmail('');
      setPassword('');
      API.defaults.headers.common['Authorization'] = `Bearer ${res.data.token}`;
      fetchTransactions();
      fetchSummary();
    } catch (err) {
      alert('로그인 실패');
    }
  };

  const handleAddTransaction = async () => {
    if (!form.amount) {
      alert('금액을 입력하세요');
      return;
    }
    try {
      await API.post('/transactions', { ...form, amount: parseFloat(form.amount) });
      setForm({ type: 'expense', category: '식비', amount: '', description: '', date: new Date().toISOString().split('T')[0] });
      fetchTransactions();
      fetchSummary();
    } catch (err) {
      alert('거래 추가 실패');
    }
  };

  const handleDeleteTransaction = async (id) => {
    try {
      await API.delete(`/transactions/${id}`);
      fetchTransactions();
      fetchSummary();
    } catch (err) {
      alert('거래 삭제 실패');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    setUser(null);
    setTransactions([]);
    setSummary({ income: 0, expense: 0 });
    API.defaults.headers.common['Authorization'] = '';
  };

  if (!user) {
    return (
      <div className="container">
        <h1>가계부</h1>
        <div className="auth-box">
          <input placeholder="이메일" value={email} onChange={(e) => setEmail(e.target.value)} type="email" />
          <input placeholder="비밀번호" value={password} onChange={(e) => setPassword(e.target.value)} type="password" />
          <button onClick={handleSignup}>회원가입</button>
          <button onClick={handleSignin}>로그인</button>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <div className="header">
        <h1>가계부</h1>
        <div>{user.email}</div>
        <button onClick={handleLogout}>로그아웃</button>
      </div>

      <div className="summary">
        <div className="summary-item income">
          <span>수입:</span>
          <span>₩{summary.income.toLocaleString()}</span>
        </div>
        <div className="summary-item expense">
          <span>지출:</span>
          <span>₩{summary.expense.toLocaleString()}</span>
        </div>
        <div className="summary-item balance">
          <span>잔액:</span>
          <span>₩{(summary.income - summary.expense).toLocaleString()}</span>
        </div>
      </div>

      <div className="form-box">
        <select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}>
          <option value="income">수입</option>
          <option value="expense">지출</option>
        </select>

        <select value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })}>
          <option value="식비">식비</option>
          <option value="교통">교통</option>
          <option value="쇼핑">쇼핑</option>
          <option value="의료">의료</option>
          <option value="급여">급여</option>
          <option value="기타">기타</option>
        </select>

        <input type="number" placeholder="금액" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} />
        <input type="text" placeholder="설명" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} />
        <input type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
        <button onClick={handleAddTransaction}>추가</button>
      </div>

      <div className="transactions">
        <h2>거래 내역</h2>
        {transactions.map((t) => (
          <div key={t.id} className={`transaction ${t.type}`}>
            <div className="transaction-info">
              <div className="category">{t.category}</div>
              <div className="description">{t.description || '-'}</div>
              <div className="date">{t.date}</div>
            </div>
            <div className="transaction-amount">
              <span className={t.type}>{t.type === 'income' ? '+' : '-'}₩{t.amount.toLocaleString()}</span>
              <button onClick={() => handleDeleteTransaction(t.id)}>삭제</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
```

