    </div>
    <script>
        const ROWS = 20, COLS = 10;
        const TETROMINOES = [
            { shape: [[1,1,1,1]], color: "#FF6B6B" },
            { shape: [[1,1],[1,1]], color: "#4ECDC4" },
            { shape: [[0,1,1],[1,1,0]], color: "#FFE66D" },
            { shape: [[1,1,0],[0,1,1]], color: "#95E1D3" },
            { shape: [[1,0,0],[1,1,1]], color: "#C7CEEA" },
            { shape: [[0,0,1],[1,1,1]], color: "#FF9999" },
            { shape: [[0,1,0],[1,1,1]], color: "#A8D8EA" }
        ];
        let board = Array(ROWS).fill(null).map(() => Array(COLS).fill(null));
        let currentPiece = null, nextPiece = null, score = 0, lines = 0, level = 1;
        let gameRunning = false, gamePaused = false, dropInterval = null;

        function initGame() {
            board = Array(ROWS).fill(null).map(() => Array(COLS).fill(null));
            score = lines = 0; level = 1; gameRunning = true; gamePaused = false;
            currentPiece = getRandomPiece(); nextPiece = getRandomPiece(); updateUI(); startDrop();
        }

        function getRandomPiece() {
            const t = TETROMINOES[Math.floor(Math.random() * TETROMINOES.length)];
            return { shape: t.shape, color: t.color, x: Math.floor(COLS / 2) - Math.floor(t.shape[0].length / 2), y: 0 };
        }

        function drawBoard() {
            const gb = document.getElementById("gameBoard");
            gb.innerHTML = "";
            for (let r = 0; r < ROWS; r++) {
                for (let c = 0; c < COLS; c++) {
                    const cell = document.createElement("div");
                    cell.className = "cell";
                    if (board[r][c]) { cell.classList.add("filled"); cell.style.color = board[r][c]; }
                    gb.appendChild(cell);
                }
            }
            if (currentPiece) {
                currentPiece.shape.forEach((row, y) => {
                    row.forEach((val, x) => {
                        if (val) {
                            const r = currentPiece.y + y, c = currentPiece.x + x;
                            if (r >= 0 && r < ROWS && c >= 0 && c < COLS) {
                                const idx = r * COLS + c;
                                if (!board[r][c]) { gb.children[idx].classList.add("filled"); gb.children[idx].style.color = currentPiece.color; }
                            }
                        }
                    });
                });
            }
        }

        function drawNextPiece() {
            const ng = document.getElementById("nextGrid");
            ng.innerHTML = "";
            for (let i = 0; i < 16; i++) {
                const cell = document.createElement("div");
                cell.className = "cell";
                ng.appendChild(cell);
            }
            if (nextPiece) {
                nextPiece.shape.forEach((row, y) => {
                    row.forEach((val, x) => {
                        if (val) {
                            const idx = y * 4 + x;
                            ng.children[idx].classList.add("filled");
                            ng.children[idx].style.color = nextPiece.color;
                        }
                    });
                });
            }
        }

        function canMove(piece, newX, newY) {
            for (let y = 0; y < piece.shape.length; y++) {
                for (let x = 0; x < piece.shape[y].length; x++) {
                    if (piece.shape[y][x]) {
                        const bX = newX + x, bY = newY + y;
                        if (bX < 0 || bX >= COLS || bY >= ROWS) return false;
                        if (bY >= 0 && board[bY][bX]) return false;
                    }
                }
            }
            return true;
        }

        function lockPiece() {
            currentPiece.shape.forEach((row, y) => {
                row.forEach((val, x) => {
                    if (val) {
                        const r = currentPiece.y + y, c = currentPiece.x + x;
                        if (r >= 0 && r < ROWS && c >= 0 && c < COLS) board[r][c] = currentPiece.color;
                    }
                });
            });
            checkLines(); currentPiece = nextPiece; nextPiece = getRandomPiece();
            if (!canMove(currentPiece, currentPiece.x, currentPiece.y)) endGame();
        }

        function checkLines() {
            let completed = 0;
            for (let r = ROWS - 1; r >= 0; r--) {
                if (board[r].every(c => c !== null)) {
                    board.splice(r, 1);
                    board.unshift(Array(COLS).fill(null));
                    completed++; r++;
                }
            }
            if (completed > 0) {
                lines += completed; score += completed * 100 * level; level = Math.floor(lines / 10) + 1; updateUI();
            }
        }

        function rotatePiece() {
            const rotated = currentPiece.shape[0].map((_, colIndex) => currentPiece.shape.map(row => row[colIndex]).reverse());
            const oldShape = currentPiece.shape;
            currentPiece.shape = rotated;
            if (!canMove(currentPiece, currentPiece.x, currentPiece.y)) currentPiece.shape = oldShape;
        }

        function movePiece(dx, dy) {
            if (canMove(currentPiece, currentPiece.x + dx, currentPiece.y + dy)) {
                currentPiece.x += dx; currentPiece.y += dy; return true;
            }
            return false;
        }

        function drop() {
            if (!gameRunning || gamePaused) return;
            if (!movePiece(0, 1)) lockPiece();
            drawBoard();
        }

        function startDrop() {
            dropInterval = setInterval(drop, Math.max(100, 500 - level * 50));
        }

        function updateUI() {
            document.getElementById("score").textContent = score;
            document.getElementById("level").textContent = level;
            document.getElementById("lines").textContent = lines;
            drawBoard(); drawNextPiece();
        }

        function endGame() {
            gameRunning = false; clearInterval(dropInterval);
            document.getElementById("finalScore").textContent = `최종 점수: ${score}`;
            document.getElementById("gameOverScreen").style.display = "block";
        }

        document.getElementById("startBtn").addEventListener("click", () => {
            if (!gameRunning) { initGame(); document.getElementById("startBtn").textContent = "다시 시작"; }
        });

        document.getElementById("pauseBtn").addEventListener("click", () => {
            if (gameRunning) {
                gamePaused = !gamePaused;
                document.getElementById("pauseBtn").textContent = gamePaused ? "재개" : "일시정지";
            }
        });

        document.addEventListener("keydown", (e) => {
            if (!gameRunning || gamePaused) return;
            switch(e.key) {
                case "ArrowLeft": movePiece(-1, 0); break;
                case "ArrowRight": movePiece(1, 0); break;
                case "ArrowDown": drop(); break;
                case "z":
                case "Z": rotatePiece(); break;
                case " ": e.preventDefault(); while (movePiece(0, 1)); lockPiece(); break;
            }
            drawBoard();
        });

        drawBoard(); drawNextPiece();
    </script>
</body>
</html>
```

## 게임 기능

- **게임 보드**: 10x20 격자
- **테트로미노**: 7가지 다양한 모양의 블록
- **점수 시스템**: 줄을 완성할 때마다 점수 획득, 레벨이 올라갈수록 배수 증가
- **난이도 조정**: 레벨이 올라가면서 블록이 빠르게 떨어짐
- **다음 블록 미리보기**
- **일시정지 기능**

## 조작 방법

- **← →**: 블록 좌우 이동
- **↓**: 빠른 하강
- **Z**: 블록 회전
- **스페이스**: 즉시 하강

위 코드를 텍스트 편집기에 복사해서 `tetris.html`로 저장한 후 웹 브라우저에서 열면 됩니다!

사용자님이 "아무거나로 정해서 지금 만들어 주세요"라고 하셨으므로, 코드를 직접 출력해서 제공하겠습니다. 복사해서 프로젝트에 저장하시면 됩니다.

## 📦 가계부 앱 완전 구성

### **백엔드 - server.js**

```javascript
import express from 'express';
import sqlite3 from 'sqlite3';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';
import cors from 'cors';

const app = express();
const PORT = 3001;
const JWT_SECRET = 'household-app-secret-key';

app.use(cors());
app.use(express.json());

const db = new sqlite3.Database('./household.db');

db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS transactions (
    id INTEGER PRIMARY KEY,
    user_id INTEGER NOT NULL,
    type TEXT NOT NULL,
    amount REAL NOT NULL,
    category TEXT NOT NULL,
    description TEXT,
    date DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id)
  )`);
});

// 회원가입
app.post('/api/auth/signup', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: '필수 정보 필요' });

  const hashedPassword = bcrypt.hashSync(password, 10);
  db.run('INSERT INTO users (username, password) VALUES (?, ?)', [username, hashedPassword], function (err) {
    if (err) return res.status(400).json({ error: '이미 존재하는 사용자명' });
    const token = jwt.sign({ userId: this.lastID }, JWT_SECRET, { expiresIn: '7d' });
    res.status(201).json({ token, userId: this.lastID, username });
  });
});

// 로그인
app.post('/api/auth/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: '필수 정보 필요' });

  db.get('SELECT * FROM users WHERE username = ?', [username], (err, user) => {
    if (!user || !bcrypt.compareSync(password, user.password)) {
      return res.status(401).json({ error: '로그인 실패' });
    }
    const token = jwt.sign({ userId: user.id }, JWT_SECRET, { expiresIn: '7d' });
    res.json({ token, userId: user.id, username: user.username });
  });
});

// 인증 미들웨어
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];
  if (!token) return res.status(401).json({ error: '토큰 필요' });

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: '유효하지 않은 토큰' });
    req.user = user;
    next();
  });
};

// 거래 추가
app.post('/api/transactions', authenticateToken, (req, res) => {
  const { type, amount, category, description, date } = req.body;
  const userId = req.user.userId;
  if (!type || !amount || !category) return res.status(400).json({ error: '필수 정보 필요' });

  db.run(
    'INSERT INTO transactions (user_id, type, amount, category, description, date) VALUES (?, ?, ?, ?, ?, ?)',
    [userId, type, amount, category, description, date || new Date().toISOString()],
    function (err) {
      if (err) return res.status(500).json({ error: '추가 실패' });
      res.status(201).json({ id: this.lastID, type, amount, category, description, date });
    }
  );
});

// 거래 조회
app.get('/api/transactions', authenticateToken, (req, res) => {
  db.all('SELECT * FROM transactions WHERE user_id = ? ORDER BY date DESC', [req.user.userId], (err, rows) => {
    if (err) return res.status(500).json({ error: '조회 실패' });
    res.json(rows || []);
  });
});

// 거래 수정
app.put('/api/transactions/:id', authenticateToken, (req, res) => {
  const { type, amount, category, description, date } = req.body;
  db.run(
    'UPDATE transactions SET type = ?, amount = ?, category = ?, description = ?, date = ? WHERE id = ? AND user_id = ?',
    [type, amount, category, description, date, req.params.id, req.user.userId],
    function (err) {
      if (err || this.changes === 0) return res.status(404).json({ error: '실패' });
      res.json({ id: req.params.id, type, amount, category, description, date });
    }
  );
});

// 거래 삭제
app.delete('/api/transactions/:id', authenticateToken, (req, res) => {
  db.run('DELETE FROM transactions WHERE id = ? AND user_id = ?', [req.params.id, req.user.userId], function (err) {
    if (err || this.changes === 0) return res.status(404).json({ error: '실패' });
    res.status(204).send();
  });
});

app.listen(PORT, () => console.log(`서버 실행: http://localhost:${PORT}`));
```

