}

.transactions h2 {
  margin-bottom: 15px;
  color: #333;
}

.transactions ul {
  list-style: none;
}

.transactions li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px;
  border-bottom: 1px solid #eee;
}

.transactions li:last-child {
  border-bottom: none;
}

.category {
  font-weight: bold;
  color: #667eea;
  display: block;
}

.description {
  font-size: 12px;
  color: #999;
  display: block;
}

.amount {
  font-weight: bold;
  margin-right: 10px;
}

.delete {
  background: #ef4444;
  color: white;
  border: none;
  border-radius: 4px;
  padding: 4px 8px;
  cursor: pointer;
  font-size: 12px;
}

.empty {
  text-align: center;
  color: #999;
  padding: 40px 20px;
}

@media (max-width: 768px) {
  .summary {
    grid-template-columns: 1fr;
  }

  .form {
    grid-template-columns: 1fr;
  }
}
```

